<template><div ref="root" class="bio-live-select"><button type="button" class="bio-nexus-field bio-live-trigger" :disabled="disabled" @click="toggle"><span>{{ selectedLabel }}</span><BioNexusIcon name="expand_more" :size="20" /></button><section v-if="open" class="bio-live-popup"><input ref="searchInput" v-model="search" class="bio-nexus-field" type="search" :placeholder="searchPlaceholder" autocomplete="off"><div class="bio-live-options"><button v-for="option in filtered" :key="valueOf(option)" type="button" :class="{selected:valueOf(option)===modelValue}" @click="choose(option)"><strong>{{ labelOf(option) }}</strong><small v-if="descriptionOf(option)">{{ descriptionOf(option) }}</small></button><p v-if="filtered.length===0">No existen coincidencias.</p></div></section></div></template>
<script setup>import{computed,nextTick,onBeforeUnmount,ref}from"vue";import BioNexusIcon from"@/components/ui/BioNexusIcon.vue";const props=defineProps({modelValue:{type:[Number,String],default:0},options:{type:Array,default:()=>[]},labelKey:{type:String,default:"description"},valueKey:{type:String,default:"id"},descriptionKey:{type:String,default:""},placeholder:{type:String,default:"Selecciona una opción"},searchPlaceholder:{type:String,default:"Buscar"},disabled:Boolean}),emit=defineEmits(["update:modelValue","change"]),root=ref(null),searchInput=ref(null),open=ref(false),search=ref("");const valueOf=o=>o?.[props.valueKey],labelOf=o=>String(o?.[props.labelKey]||""),descriptionOf=o=>props.descriptionKey?String(o?.[props.descriptionKey]||""):"",selected=computed(()=>props.options.find(o=>valueOf(o)===props.modelValue)),selectedLabel=computed(()=>selected.value?labelOf(selected.value):props.placeholder),filtered=computed(()=>{const q=search.value.trim().toLowerCase();return q?props.options.filter(o=>[labelOf(o),descriptionOf(o)].some(v=>v.toLowerCase().includes(q))):props.options});async function toggle(){if(props.disabled)return;open.value=!open.value;if(open.value){search.value="";await nextTick();searchInput.value?.focus()}}function choose(option){const value=valueOf(option);emit("update:modelValue",value);emit("change",option);open.value=false}function outside(event){if(open.value&&!root.value?.contains(event.target))open.value=false}document.addEventListener("pointerdown",outside);onBeforeUnmount(()=>document.removeEventListener("pointerdown",outside));</script>
<style scoped>.bio-live-select{position:relative;min-width:0}.bio-live-trigger{display:flex;align-items:center;justify-content:space-between;gap:10px;width:100%;text-align:left}.bio-live-trigger span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.bio-live-popup{position:absolute;z-index:40;top:calc(100% + 6px);left:0;right:0;display:grid;gap:6px;padding:8px;border:1px solid var(--bio-nexus-color-border-strong);border-radius:var(--bio-nexus-radius-md);background:var(--bio-nexus-color-surface);box-shadow:var(--bio-nexus-shadow-md)}.bio-live-options{display:grid;max-height:280px;overflow:auto}.bio-live-options button{display:grid;gap:2px;padding:9px 10px;border:0;border-bottom:1px solid var(--bio-nexus-color-border);background:transparent;text-align:left;cursor:pointer}.bio-live-options button:hover,.bio-live-options button.selected{background:var(--bio-nexus-color-info-soft)}.bio-live-options small,.bio-live-options p{color:var(--bio-nexus-color-text-muted)}.bio-live-options p{padding:10px;margin:0;text-align:center}</style>
